<?php
/** TEMP PS S1677 run o — petshop-ads-offline v1.1 DEPLOY (D) + endpoint testas (T). */
add_action('init', function(){
  if (!isset($_GET['ps_s1677o'])) return; global $wpdb; $p=$wpdb->prefix; $F=$_GET['ps_s1677o']; $o=array('v'=>'S1677 o','faze'=>$F);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $f1=WPMU_PLUGIN_DIR.'/petshop-ads-offline.php';
  if($F==='D'){ $k1=base64_decode('');
    if(md5($k1)!=='04708b969ac697f2a2eccbfb93b415b2'){ $o['STOP']='b64 md5'; } elseif(@token_get_all($k1,TOKEN_PARSE)===false){ $o['STOP']='sintaksė'; }
    else { if(!get_option('ps_ads_offline_raktas')) update_option('ps_ads_offline_raktas',wp_generate_password(32,false),false);
      file_put_contents($f1,$k1); $o['md5']=md5_file($f1);
      $r=wp_remote_get(home_url('/?ps_ping_s1677o='.time()),array('timeout'=>25,'sslverify'=>false)); $c=is_wp_error($r)?'ERR':wp_remote_retrieve_response_code($r); $o['ping']=$c;
      if(is_wp_error($r)||$c>=500){ unlink($f1); $o['ROLLBACK']=1; } } }
  if($F==='T'){ $k=get_option('ps_ads_offline_raktas'); $o['raktas']=$k;
    $r=wp_remote_get(home_url('/?ps_ads_offline='.$k.'&dienos=5'),array('timeout'=>40,'sslverify'=>false)); $o['http']=wp_remote_retrieve_response_code($r); $b=json_decode(wp_remote_retrieve_body($r),true);
    $o['n']=$b['n']??null; $o['pvz']=array_slice($b['eil']??array(),0,3); foreach($o['pvz'] as &$e){ $e['gclid']=substr($e['gclid'],0,12).'…'; } unset($e);
    $o['fakt_gclid_viso']=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}ps_fakt_uzsakymai WHERE testinis=0 AND gclid<>''"); }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT); exit;
});
